import React from "react";
import { AbsoluteFill, Img, useCurrentFrame, interpolate, Easing } from "remotion";
import { COLORS, FONTS, STYLE, ENGRAVE_SHADOW } from "../style-tokens";
import type { PrimitiveProps } from "../primitives";

const CLAMP = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const WHITE = "rgba(255,255,255,1)";

const TituloQuatroFaixasImagens: React.FC<PrimitiveProps> = ({ anim, fps, dark, format, frame }) => {
  const f = useCurrentFrame();
  const params = (anim.params ?? {}) as Record<string, unknown>;
  // `src` is the pipeline's slot; src2..src4 (or a srcs array) carry the other strips.
  const src = String(anim.params?.src ?? "");
  const list = Array.isArray(params.srcs) ? (params.srcs as unknown[]) : [];
  const srcs = [0, 1, 2, 3].map((i) => String((i === 0 ? src : params[`src${i + 1}`]) || list[i] || ""));
  const text = String(anim.text ?? "").trim();

  const len = Math.max(1, Math.round((anim.end - anim.start) * fps));
  const short = Math.min(frame.width, frame.height);
  const portrait = format === "portrait";
  const landscape = format === "landscape";
  const padX = Math.round(frame.width * (landscape ? 0.03 : 0.04));
  const padTop = Math.round(frame.height * (portrait ? 0.08 : 0.04));
  const padBottom = Math.round(frame.height * (portrait ? 0.07 : 0.04));
  const gap = Math.round(short * (format === "half" ? 0.01 : 0.014));
  const radius = STYLE.sharp ? 0 : Math.round(short * 0.012);
  const muted = dark ? COLORS.mutedOnDark : COLORS.mutedOnLight;

  // Compact title so the strips own most of the frame; long titles shrink and wrap, never clip.
  const base = short * (portrait ? 0.075 : format === "half" ? 0.055 : 0.058);
  const fontSize = Math.round(base * Math.min(1, Math.sqrt(28 / Math.max(28, text.length))));

  // Brand motion: ~250ms fade + short rise, no bounce.
  const titleIn = interpolate(f, [0, Math.round(fps * 0.25)], [0, 1], { ...CLAMP, easing: Easing.out(Easing.cubic) });
  const stripsFrom = text ? Math.round(fps * 0.3) : 0;
  const stagger = Math.max(3, Math.min(Math.round(fps * 0.3), Math.round((len * 0.5 - stripsFrom) / 4)));
  const exitStart = Math.max(0, len - Math.round(fps * 0.3));

  return (
    <AbsoluteFill
      style={{
        fontFamily: FONTS.display,
        opacity: interpolate(f, [exitStart, Math.max(exitStart + 1, len)], [1, 0], CLAMP),
        padding: `${padTop}px ${padX}px ${padBottom}px`,
        flexDirection: "column",
        gap: Math.round(short * 0.028),
      }}
    >
      {text ? (
        <div
          style={{
            flex: "0 0 auto",
            alignSelf: "center",
            maxWidth: landscape ? "80%" : "100%",
            fontSize,
            fontWeight: FONTS.displayWeight,
            lineHeight: 1.1,
            textAlign: "center",
            textTransform: STYLE.uppercaseTitles ? "uppercase" : "none",
            overflowWrap: "break-word",
            color: WHITE,
            textShadow: ENGRAVE_SHADOW,
            opacity: titleIn,
            transform: `translateY(${(1 - titleIn) * short * 0.022}px)`,
          }}
        >
          {text}
        </div>
      ) : null}
      <div style={{ flex: 1, minHeight: 0, display: "flex", flexDirection: "column", gap }}>
        {srcs.map((s, i) => {
          const start = stripsFrom + i * stagger;
          const p = interpolate(f, [start, start + Math.round(fps * 0.5)], [0, 1], {
            ...CLAMP,
            easing: Easing.bezier(0.16, 1, 0.3, 1),
          });
          // Alternate sides: even strips come from the left, odd from the right.
          const dir = i % 2 === 0 ? -1 : 1;
          // Slow drift against the entrance keeps the photo alive once it lands.
          const drift = interpolate(f, [start, Math.max(start + 1, len)], [0, -dir * 3], CLAMP);
          return (
            <div
              key={i}
              style={{
                flex: 1,
                minHeight: 0,
                position: "relative",
                overflow: "hidden",
                borderRadius: radius,
                backgroundColor: `${COLORS.leather}1F`,
                opacity: interpolate(p, [0, 0.3], [0, 1], CLAMP),
                transform: `translateX(${dir * (1 - p) * 110}%)`,
              }}
            >
              {s ? (
                <Img
                  src={s}
                  style={{
                    width: "100%",
                    height: "100%",
                    objectFit: "cover",
                    transform: `scale(1.1) translateX(${drift}%)`,
                  }}
                />
              ) : (
                <div style={{ position: "absolute", inset: 0, display: "flex", alignItems: "center", justifyContent: "center" }}>
                  <div
                    style={{
                      width: Math.round(short * 0.07),
                      height: Math.round(short * 0.05),
                      border: `${Math.max(2, Math.round(short * 0.0025))}px solid ${muted}`,
                      opacity: 0.6,
                    }}
                  />
                </div>
              )}
            </div>
          );
        })}
      </div>
    </AbsoluteFill>
  );
};

export default TituloQuatroFaixasImagens;

